<?php declare(strict_types=1); require_once __DIR__.'/../app/App.php'; if(Auth::check())redirect('dashboard.php'); $errors=[];$email=''; if(requestMethod()==='POST'){Csrf::requireValid($_POST['_csrf']??null);$email=trim((string)($_POST['email']??''));$password=(string)($_POST['password']??'');if(!filter_var($email,FILTER_VALIDATE_EMAIL)||$password==='')$errors[]='Enter a valid email address and password.';else{try{Auth::login(App::api(),$email,$password);redirect('dashboard.php');}catch(ApiException $e){$errors[]=$e->getMessage();}catch(Throwable){$errors[]='Unable to sign in right now. Please try again.';}}} App::render('auth/login',['title'=>'Sign in','errors'=>$errors,'email'=>$email],'guest');
